custom_css:
/* Zen Minimalist Theme */
:root {
  --subtle-shadow: 0 2px 20px hsl(var(--primary) / 0.08);
  --zen-gradient: linear-gradient(180deg, hsl(var(--background)), hsl(var(--secondary) / 0.3));
}

.card {
  background: hsl(var(--background));
  border: 1px solid hsl(var(--primary) / 0.1);
  box-shadow: var(--subtle-shadow);
}

.nav-item {
  font-weight: 400;
  letter-spacing: 0.05em;
  transition: color 0.2s ease;
}

.nav-item:hover {
  color: hsl(var(--primary));
}

.chapter-card {
  transition: all 0.2s ease;
  border: none;
  background: transparent;
}

.chapter-card:hover {
  background: hsl(var(--secondary) / 0.3);
  transform: translateY(-2px);
}

h1, h2, h3 {
  font-weight: 300;
  letter-spacing: -0.02em;
  line-height: 1.2;
}

.btn-primary {
  background: hsl(var(--primary));
  border-radius: 2rem;
  font-weight: 400;
  letter-spacing: 0.02em;
}

body {
  font-weight: 300;
  line-height: 1.7;
}
